<?php
declare(strict_types=1);
require_once __DIR__.'/cpms/includes/resident_session.php';cpmsResidentSessionStart();require_once __DIR__.'/db.php';require_once __DIR__.'/cpms/includes/resident_portal_service.php';
$r=cpmsResidentRequire($conn);$pid=(int)$r['property_id'];$rid=(int)$r['id'];
$s=$conn->prepare("SELECT sr.request_reference,sr.request_type,sr.subject,sr.status,sr.submitted_at,sr.id,l.complaint_reference,w.work_order_reference FROM cpms_resident_service_requests sr LEFT JOIN cpms_resident_request_links l ON l.service_request_id=sr.id LEFT JOIN work_orders w ON w.id=l.work_order_id WHERE sr.property_id=? AND sr.resident_id=? ORDER BY sr.id DESC");$s->bind_param('ii',$pid,$rid);$s->execute();$rows=$s->get_result()->fetch_all(MYSQLI_ASSOC);$s->close();
function e($v):string{return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Permohonan Resident</title><link rel="stylesheet" href="resident_portal.css?v=351">    <link rel="stylesheet" href="assets/genesis/resident-genesis.css?v=4.0.0">
</head><body><header class="rp-head"><div class="rp-wrap"><h1>Permohonan Saya</h1><p>Servis dan bantuan property</p></div></header><nav class="rp-nav"><a href="resident_dashboard.php">Dashboard</a><a href="resident_requests.php">Permohonan</a><a href="resident_announcements.php">Notis</a><a href="resident_profile.php">Profil</a></nav><main class="rp-main rp-wrap"><p><a class="rp-btn" href="resident_request_new.php">+ Permohonan Baharu</a></p><section class="rp-list"><?php if(!$rows):?><div class="rp-card">Belum ada permohonan.</div><?php endif;foreach($rows as $x):?><article class="rp-card"><div class="rp-row"><strong><?=e($x['request_reference'])?></strong><span class="rp-badge"><?=e($x['status'])?></span></div><h3><?=e($x['subject'])?></h3><p class="rp-muted"><?=e($x['request_type'])?> · <?=e(date('d/m/Y H:i',strtotime($x['submitted_at'])))?></p><p>Complaint: <strong><?=e($x['complaint_reference']??'-')?></strong> · Work Order: <strong><?=e($x['work_order_reference']??'-')?></strong></p><a href="resident_request_view.php?id=<?=(int)$x['id']?>">Lihat perkembangan →</a></article><?php endforeach;?></section></main></body></html>
